-- Refuse an unsafe historical parent/tenant relationship before enabling policies.
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM public.support_messages c JOIN public.support_tickets p ON p.id=c.ticket_id WHERE c.merchant_id<>p.merchant_id)
     OR EXISTS (SELECT 1 FROM public.support_inspection_requests c JOIN public.support_tickets p ON p.id=c.ticket_id WHERE c.merchant_id<>p.merchant_id)
     OR EXISTS (SELECT 1 FROM public.support_attachments c JOIN public.support_messages p ON p.id=c.message_id WHERE c.merchant_id<>p.merchant_id OR c.ticket_id<>p.ticket_id)
     OR EXISTS (SELECT 1 FROM public.support_preview_sessions c JOIN public.support_inspection_requests p ON p.id=c.request_id WHERE c.merchant_id<>p.merchant_id OR c.ticket_id<>p.ticket_id)
  THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Support tenant relationship preflight failed';
  END IF;
END
$$;
