ALTER TABLE public."support_tickets" ENABLE ROW LEVEL SECURITY;
--> statement-breakpoint
CREATE POLICY "support_tickets_privacy_boundary" ON public."support_tickets" AS PERMISSIVE FOR ALL TO public USING ((CASE WHEN (has_function_privilege(session_user, 'public.fawri_authentication_runtime()', 'EXECUTE') AND EXISTS (SELECT 1 FROM pg_catalog.pg_roles r WHERE r.rolname = session_user AND r.rolcanlogin AND NOT (r.rolsuper OR r.rolbypassrls OR r.rolcreaterole))) THEN true WHEN has_function_privilege(session_user, 'public.fawri_issue_admin_directory_audit(text,text,text)', 'EXECUTE') THEN false ELSE public.fawri_tenant_or_audited_admin("support_tickets"."merchant_id") END)) WITH CHECK ((CASE WHEN (has_function_privilege(session_user, 'public.fawri_authentication_runtime()', 'EXECUTE') AND EXISTS (SELECT 1 FROM pg_catalog.pg_roles r WHERE r.rolname = session_user AND r.rolcanlogin AND NOT (r.rolsuper OR r.rolbypassrls OR r.rolcreaterole))) THEN true WHEN has_function_privilege(session_user, 'public.fawri_issue_admin_directory_audit(text,text,text)', 'EXECUTE') THEN false ELSE public.fawri_tenant_or_audited_admin("support_tickets"."merchant_id") END));
